/// // indexes are:   0  1  2  3  4  5   6   7
/// assert_eq!(vec2, [0, 2, 4, 6, 8, 10, 12, 14]);
///
/// let bool_vec = Vec::from_fn(5, |i| i % 2 == 0);
///
/// // indexes are:       0     1      2     3      4
/// assert_eq!(bool_vec, [true, false, true, false, true]);
/// ```
///
